parameters.jsCode:
// O n8n sempre fornece os dados de entrada em items[0].json
// No caso, recebemos algo como:
// [
//   {
//     "output": "Oi Guilherme! Tudo bem?  \nPara começar, preciso do seu e-mail para mantermos o contato.  \nE me conta, qual é a situação jurídica que você está enfrentando? Assim consigo entender melhor e indicar a área certa."
//   }
// ]

// Primeiro, acessamos o "output"
const texto = items[0].json.output;

// Quebramos o texto por quebras de linha "\n"
const partes = texto.split("\n");

// Agora vamos retornar cada parte como um item separado no n8n
return partes
  // Limpamos espaços extras
  .map(p => p.trim())
  // Removemos linhas vazias
  .filter(p => p.length > 0)
  // Transformamos em um array de objetos
  .map(p => {
    return { json: { output: p } };
  });
